```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

/// Key under which the most recent input is recorded in the shared store.
const LAST_INPUT_KEY: &str = "last-input";

/// How many times the notification is offered before the node gives up.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input received on this call. `state-rw` is not in the
        // node's current `with` clause: it is imported per the platform-team
        // extension, ahead of the graph definition being updated. The host
        // must bind it for this component to instantiate.
        state_rw::put(LAST_INPUT_KEY, &feed_url);

        // Clock: the time this heartbeat read.
        let seconds = wall_clock::now().seconds;

        // HTTPClient: the one permitted fetch. A transport failure is a value
        // and counts as zero characters; a URL outside the allowlist traps at
        // the boundary and is not handled here.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: the message carries only the numbers read, not the
        // fetched body.
        let message = format!("heartbeat: seconds={seconds} fetched={fetched}");
        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        // ensures notified == true. If the channel never accepted the
        // notification, there is no honest output that satisfies the
        // contract, so the node traps rather than report a false `true`.
        if !notified {
            panic!("notifier did not accept the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

